async function submitSignUp(){const name=document.getElementById("signup-name")?.value.trim(),email=document.getElementById("signup-email")?.value.trim(),password=document.getElementById("signup-password")?.value||"",confirm=document.getElementById("signup-confirm")?.value||"",role=document.getElementById("signup-role")?.value||"RT_OPERATOR",m=document.getElementById("signup-msg");if(!sb){m.textContent="Supabase belum tersambung.";m.className="modal-msg error";return}if(!name||!email||password.length<8||password!==confirm){m.textContent="Lengkapi data. Password minimal 8 karakter dan harus sama.";m.className="modal-msg error";return}const r=await sb.auth.signUp({email,password,options:{emailRedirectTo:PUBLIC_URL(),data:{display_name:name,requested_role:role}}});if(r.error){m.textContent=r.error.message;m.className="modal-msg error";return}setSelectedRole(role);m.textContent="Pendaftaran berhasil. Cek email untuk verifikasi akun. Dashboard belum dapat dibuka sebelum email diverifikasi.";m.className="modal-msg success";const btn=document.querySelector("[data-signup-submit]");if(btn)btn.disabled=true}
async function submitSignIn(){const email=document.getElementById("auth-email")?.value.trim(),password=document.getElementById("auth-password")?.value||"",role=document.getElementById("auth-role")?.value||selectedRole(),m=document.getElementById("auth-msg");if(!sb){m.textContent="Supabase belum tersambung.";m.className="modal-msg error";return}if(!email||!password){m.textContent="Email dan password wajib diisi.";m.className="modal-msg error";return}setSelectedRole(role);const r=await sb.auth.signInWithPassword({email,password});if(r.error){m.textContent="Login gagal: "+r.error.message;m.className="modal-msg error";return}if(!verified(r.data?.user)){await sb.auth.signOut({scope:"local"});m.textContent="Email belum diverifikasi. Buka email konfirmasi terlebih dahulu.";m.className="modal-msg error";return}const ti=trialInfo(r.data?.user);if(ti&&!ti.active){await sb.auth.signOut({scope:"local"});m.textContent="Mode pengembangan belum memiliki masa kedaluwarsa.";m.className="modal-msg error";return}closeModal();await render()}
function signUp(){if(!sb){modal("Konfigurasi belum siap","<p>Supabase belum tersambung. Pendaftaran akun membutuhkan koneksi autentikasi.</p>");return}const body=`<p><b>Email wajib diverifikasi.</b> Pilih dashboard yang ingin digunakan. Pilihan ini hanya menandai kebutuhan akses; privilege sebenarnya tetap ditentukan oleh <b>role assignment + scope + RLS</b>.</p><label>Nama</label><input id="signup-name" autocomplete="name" placeholder="Nama lengkap"><label>Fungsi / Privilege</label><select id="signup-role">${roleOptions(selectedRole(),true)}</select><label>Email</label><input id="signup-email" type="email" autocomplete="email" placeholder="nama@contoh.id"><label>Password</label><input id="signup-password" type="password" autocomplete="new-password" placeholder="Minimal 8 karakter"><label>Ulangi Password</label><input id="signup-confirm" type="password" autocomplete="new-password" placeholder="Ulangi password"><button class="primary" data-signup-submit onclick="submitSignUp()">Buat Akun</button><div id="signup-msg" class="modal-msg"></div>`;modal("Daftar Akun",body)}
function signIn(){if(!sb){modal("Konfigurasi belum siap","<p>Supabase belum tersambung.</p>");return}const body=`<p>Email dan password digunakan untuk masuk. <b>Email harus sudah diverifikasi.</b> Pilihan dashboard membantu navigasi; privilege tidak berubah karena pilihan ini. Akses nyata mengikuti assignment, scope dan RLS.</p><label>Fungsi / Privilege</label><select id="auth-role" onchange="setSelectedRole(this.value)">${roleOptions(selectedRole(),true)}</select><label>Email terdaftar</label><input id="auth-email" type="email" autocomplete="email" placeholder="nama@contoh.id"><label>Password</label><input id="auth-password" type="password" autocomplete="current-password" placeholder="Password"><button class="primary" onclick="submitSignIn()">Sign In</button><div id="auth-msg" class="modal-msg"></div>`;modal("Sign In",body)}
