function startAdminPreview(){try{localStorage.setItem(PREVIEW_TRIAL_KEY,String(Date.now()));sessionStorage.removeItem(PREVIEW_ROLE_KEY);sessionStorage.setItem("rtrw_admin_trial_entry_v1","1");const u=new URL(PRODUCTION_URL);u.searchParams.delete("trial");u.searchParams.delete("source");u.searchParams.delete("demo");u.searchParams.set("preview","admin");u.searchParams.set("role","PLATFORM_ADMIN");location.href=u.toString()}catch(e){toast("Pratinjau Admin Utama tidak dapat dibuka: "+e.message)}} 
function landing(){document.getElementById("landing").innerHTML=`<div class="landing"><header><div class="brand"><b>RS</b><span>RT/RW–SID CONNECT<small>COMMUNITY · VILLAGE · SMART VILLAGE OS</small></span></div><span class="pilot">COMMUNITY · VILLAGE · SMART VILLAGE OS</span></header><main><section><div class="eyebrow">DIGITAL OPERATING PLATFORM</div><h1>Satu operating system untuk <em>komunitas & desa.</em></h1><p>RT/RW–SID CONNECT mengelola data warga, layanan, verifikasi, governance dan Smart Village dalam satu platform. Akses operasional mengikuti akun terverifikasi, penugasan role, scope wilayah dan kebijakan akses. Aktivasi paket komersial belum tersedia pada build ini.</p><div class="access-picker"><div><small>AKSES PENGGUNA</small><b>Masuk ke RT/RW–SID CONNECT</b><span id="landing-role-desc"></span></div><div class="role-cards" id="landing-role">${landingRoleCards()}</div></div><div class="actions"><button class="primary" onclick="startRegionalDemo()">▶ Buka Demo Interaktif Wilayah Terpilih</button><button class="ghost" onclick="startAdminPreview()">Admin Utama · Pratinjau Terpisah</button><button class="ghost" onclick="signIn()">Sign In</button><button class="ghost" onclick="signUp()">Sign Up</button></div><div class="trust"><span>✓ Role + Scope + RLS</span><span>✓ Audit & governance</span><span>ℹ Paket komersial belum diaktifkan</span></div></section><div class="landing-preview"><div class="preview-chrome"><span>● ● ●</span><b>community-data-os</b><i>SECURE WORKSPACE</i></div><div class="preview-shell"><aside><strong>RS</strong><div class="pnav active">⌂</div><div class="pnav">♙</div><div class="pnav">▣</div><div class="pnav">◈</div></aside><article><div class="preview-head"><small>ROLE-AWARE WORKSPACE</small><b>Operational Overview</b></div><div class="preview-kpis"><div><strong>1,284</strong><small>Warga</small></div><div><strong>326</strong><small>KK</small></div><div><strong>48</strong><small>Layanan</small></div></div><div class="preview-chart"><span style="height:42%"></span><span style="height:60%"></span><span style="height:50%"></span><span style="height:76%"></span><span style="height:68%"></span><span style="height:90%"></span><span style="height:82%"></span></div><div class="preview-row"><span>Progressive verification</span><b>READY</b></div></article></div></div></main><footer>RT/RW–SID CONNECT v2.0 · Community, Village & Smart Village Digital Operating Platform</footer></div>`;renderLandingRole()}
function renderLandingRole(){const code=selectedRole(),role=ROLE_DEFS[code]||ROLE_DEFS.RT_OPERATOR;const el=document.getElementById("landing-role-desc");if(el)el.textContent=role.desc;document.querySelectorAll("[data-landing-role]").forEach(x=>x.classList.toggle("active",x.dataset.landingRole===code));document.querySelectorAll("[data-landing-role]").forEach(x=>x.onclick=()=>chooseLandingRole(x.dataset.landingRole))}
function nav(){let h="";for(const g of groups){const es=Object.entries(modules).filter(([k,m])=>m[1]===g&&roleAllowedModule(access.code,k));if(!es.length)continue;h+='<div class="nav-group"><small>'+g+"</small>";for(const [k,m] of es){h+='<div class="nav-module"><button class="'+(state.view===k?"active":"")+'" data-nav-module="'+esc(k)+'" data-nav-sub="'+esc(m[2][0][0])+'"><span class="nav-icon">'+(icons[k]||"•")+"</span>"+esc(m[0])+"<b>›</b></button>";if(state.view===k)h+='<div class="nav-submenu">'+m[2].map(s=>'<button class="'+(state.sub===s[0]?"active":"")+'" data-nav-module="'+esc(k)+'" data-nav-sub="'+esc(s[0])+'">'+esc(s[1])+"</button>").join("")+"</div>";h+="</div>"}h+="</div>"}return h}
function closeMobileSidebar(){document.body.classList.remove("menu-open")}function toggleMobileSidebar(){document.body.classList.toggle("menu-open")}document.addEventListener("click",function(e){const rw=e.target.closest("[data-rw-action]");if(rw){e.preventDefault();e.stopImmediatePropagation();rwAction(rw.dataset.rwTable,rw.dataset.rwId,rw.dataset.rwTerritory,rw.dataset.rwAction);return}});
document.addEventListener("click",function(e){const el=e.target.closest("[data-nav-module][data-nav-sub]");if(!el)return;e.preventDefault();e.stopPropagation();go(el.dataset.navModule,el.dataset.navSub);closeMobileSidebar();});document.addEventListener("click",function(e){const el=e.target.closest("[data-sidebar-toggle]");if(!el)return;e.preventDefault();e.stopPropagation();if(el.dataset.sidebarToggle==="open")toggleMobileSidebar();else closeMobileSidebar();});
document.addEventListener("click",function(e){const el=e.target.closest("[data-live-action][data-live-id]");if(el){e.preventDefault();e.stopImmediatePropagation();const id=el.dataset.liveId;if(el.dataset.liveAction==="view")openLiveRecord(id);else if(el.dataset.liveAction==="update")openLiveUpdate(id);return}const up=e.target.closest("[data-row-update]");if(up){e.preventDefault();e.stopImmediatePropagation();openForm("update",up.dataset.rowUpdate);}});document.addEventListener("change",function(e){const el=e.target.closest("[data-live-select],[data-row-select]");if(!el)return;toggleRow(el.dataset.liveSelect||el.dataset.rowSelect,el.checked);});;document.addEventListener("click",function(e){const el=e.target.closest("[data-workspace-module][data-workspace-sub]");if(!el)return;e.preventDefault();e.stopPropagation();go(el.dataset.workspaceModule,el.dataset.workspaceSub);});

function go(v,s,push=true){if(push&&(state.view!==v||state.sub!==s))state.history.push([state.view,state.sub]);state.forward=[];state.view=v;state.sub=s;state.selected.clear();render()}
function back(){const h=state.history.pop();if(!h){toast("Tidak ada halaman sebelumnya");return}state.forward.push([state.view,state.sub]);state.view=h[0];state.sub=h[1];render()}
function next(){const h=state.forward.pop();if(!h){const idx=modules[state.view][2].findIndex(x=>x[0]===state.sub),a=modules[state.view][2][idx+1];if(a){state.history.push([state.view,state.sub]);state.sub=a[0];render()}else toast("Sudah di submenu terakhir");return}state.history.push([state.view,state.sub]);state.view=h[0];state.sub=h[1];render()}
function toast(msg){let x=document.getElementById("toast");if(!x){x=document.createElement("div");x.id="toast";document.body.appendChild(x)}x.textContent=msg;x.classList.add("show");clearTimeout(window.__toast);window.__toast=setTimeout(()=>x.classList.remove("show"),2200)}
