async function saveHouseholdForm(mode,id){
 if(ADMIN_PREVIEW){const root=document.getElementById("modal"),payload={members:[]};root.querySelectorAll("[id^='hh_']").forEach(el=>{payload[el.id.slice(3)]=el.value.trim()});root.querySelectorAll(".household-member").forEach((row,i)=>{const m={};row.querySelectorAll("input,select").forEach(el=>m[el.name]=el.value);m.member_no=i+1;payload.members.push(m)});payload.member_count=payload.members.length;const key="rtrw_preview_households_v1";const rows=JSON.parse(localStorage.getItem(key)||"[]");rows.unshift({id:"PREVIEW-KK-"+Date.now(),...payload,status:"DRAFT",created_at:new Date().toISOString()});localStorage.setItem(key,JSON.stringify(rows));closeModal();state.selected.clear();render();toast("✓ Data KK tersimpan di sandbox pengembangan");return}
 if(!sb){toast("Supabase belum tersambung");return}
 const root=document.getElementById("modal"),payload={members:[]};
 root.querySelectorAll("[id^='hh_']").forEach(el=>{payload[el.id.slice(3)]=el.value.trim()});
 root.querySelectorAll(".household-member").forEach((row,i)=>{const m={};row.querySelectorAll("input,select").forEach(el=>m[el.name]=el.value);m.member_no=i+1;payload.members.push(m)});
 payload.member_count=payload.members.length;
 payload.form_code="F-1.02";payload.form_version="2026";payload.result_form_code="F-1.09";payload.request_type=payload.request_kk||payload.request_type||"Membentuk keluarga baru";payload.applicant_name=payload.applicant_name||payload.head_name;
 payload.compliance={canonical_form:"F-1.02",canonical_version:"2026",result_form:"F-1.09",mapping_version:"2026-09-29"};
 payload.workflow={type:"HOUSEHOLD",initial_status:"SUBMITTED",required_stages:["RT_VERIFICATION","RW_REVIEW","DESA_VALIDATION","AUTHORIZED_PROCESSING"],source_form:"F-1.02",result_form:"F-1.09"};
 if(!payload.applicant_name||!payload.address||!payload.rt||!payload.rw||!payload.request_kk){toast("Nama pemohon, alamat, RT, RW dan jenis permohonan KK wajib diisi");return}
 if(payload.applicant_nik&&!/^\\d{16}$/.test(payload.applicant_nik)){toast("NIK pemohon harus 16 digit bila diisi");return}
 if(payload.members.some(m=>!m.full_name)){toast("Nama setiap anggota keluarga wajib diisi");return}
 const {data:{user}}=await sb.auth.getUser();if(!user){toast("Silakan Sign In untuk menyimpan");return}
 const scope=liveDemoScope();if(!scope){toast("Penugasan RT aktif belum tersedia.");return}const resp=await sb.functions.invoke("rt-transaction",{body:{service_type:"HOUSEHOLD",territory_id:scope,payload:{...payload,full_name:payload.head_name,household_number:payload.household_number}}});
 if(resp.error||!resp.data?.ok){toast("Gagal menyimpan KK: "+(resp.data?.error||resp.error?.message||"Unknown error"));return}
 closeModal();state.selected.clear();await render();toast("✓ Pengajuan KK F-1.02 tersimpan dan masuk workflow verifikasi · hasil pelayanan dipetakan ke F-1.09");
}
function openForm(mode="insert",id=null){
 if((state.view==="rt"&&state.sub==="households")||(state.view==="warga"&&state.sub==="household")){openHouseholdForm(mode,id);return}
 const s=schemaFor();if(!Array.isArray(s)||!s.length){toast("Formulir khusus untuk submenu ini belum tersedia. Penambahan data dinonaktifkan agar tidak memakai form generik.");return}
 const rows=state.rows[key()]||[],row=id?rows.find(r=>r.id===id):null,vals=row?.values||[];
 let html='<p class="form-context">Form '+esc(subTitle())+' — field disusun khusus sesuai konteks submenu ini.</p><div class="context-form">';
 s.forEach((f,i)=>{const v=vals[i]||"";html+='<label>'+esc(f[0])+'<small>context: '+esc(f[2])+'</small>';if(f[1]==="textarea")html+='<textarea id="f'+i+'" placeholder="'+esc(f[2])+'">'+esc(v)+'</textarea>';else if(f[1]==="select")html+='<select id="f'+i+'">'+f[2].split("|").map(o=>'<option value="'+esc(o)+'" '+(o===v?"selected":"")+'>'+esc(o)+'</option>').join("")+'</select>';else html+='<input id="f'+i+'" type="'+esc(f[1])+'" placeholder="'+esc(f[2])+'" value="'+esc(v)+'">';html+='</label>'});
 const jm=JSON.stringify(mode),ji=JSON.stringify(id||"");
 html+='</div><div class="form-actions"><button class="btn" onclick="closeModal()">Batal</button><button class="btn primary" onclick="saveForm('+jm+','+ji+')">'+(mode==="update"?"Update":"Insert")+'</button></div>';
 modal((mode==="update"?"Update ":"Insert ")+subTitle(),html,true);
}
async function saveForm(mode,id){
 const s=schemaFor(),values=s.map((_,i)=>document.getElementById("f"+i)?.value||"");
 if(!values[0]){toast("Field utama wajib diisi");return}
 const operationalInsert=(mode!=="update"&&(state.view==="rt"||state.view==="warga"));
 if(operationalInsert&&sb){
  try{
   const {data:{user},error:userError}=await sb.auth.getUser();
   if(userError||!user)throw new Error("Sesi login tidak tersedia. Silakan Sign In ulang.");
   const payload={};s.forEach((f,i)=>{payload[f[0]]=values[i]});
   const rtMap={deaths:"DEATH",letters:"LETTER",births:"BIRTH",moves:"MOVE",domicile:"DOMICILE",marriage:"MARRIAGE",residents:"PERSON",households:"HOUSEHOLD",verification:"VERIFICATION",complaints:"COMPLAINT",security:"SECURITY",activities:"ACTIVITY",social:"SOCIAL",health:"HEALTH",education:"EDUCATION",economy:"BUSINESS",employment:"EMPLOYMENT",trade:"TRADE",environment:"ENVIRONMENT",infrastructure:"INFRASTRUCTURE",organizations:"ORGANIZATION",volunteers:"VOLUNTEER",dues:"DUES",planning:"PLANNING",disaster:"DISASTER",dataquality:"DATAQUALITY",gis:"GIS",intelligence:"RT_INTELLIGENCE",smart:"SMART_VILLAGE",inventory:"INVENTORY",reports:"REPORT",dashboard:"RT_REPORT"};
   const wargaMap={address:"DOMICILE",services:"SERVICE_REQUEST",complaints:"COMPLAINT"};
   const service_type=(state.view==="rt"?rtMap[state.sub]:wargaMap[state.sub])||state.sub.toUpperCase();
   const scope=liveDemoScope();if(!scope){toast("Penugasan wilayah aktif belum tersedia.");return}const resp=await sb.functions.invoke("rt-transaction",{body:{service_type,territory_id:scope,payload:{...payload,full_name:payload["Nama Lengkap"]||payload["Nama Warga"]||payload["Nama"],national_id:payload["NIK"]||payload["NIK Almarhum/Almarhumah"]||payload["NIK Pemohon"],date_of_death:payload["Tanggal Kematian"],place_of_death:payload["Tempat Kematian"],cause_category:payload["Penyebab Kematian"],source_document_path:payload["Dokumen Keterangan Kematian"]}}});
   if(resp.error||!resp.data?.ok)throw new Error(resp.data?.error||resp.error?.message||"Gagal menyimpan melalui workflow");
   seedRows();state.rows[key()].unshift({id:resp.data.record?.request_number||resp.data.record?.id||"SYNC-"+Date.now(),values,status:resp.data.record?.status||"SUBMITTED",updated:"Supabase"});
   persist();closeModal();state.selected.clear();await render();toast("✓ Data tersimpan di Supabase dan masuk workflow · "+service_type);return;
  }catch(e){toast("Gagal menyimpan: "+(e?.message||"Kesalahan tidak diketahui"));return}
 }
 seedRows();
 if(mode==="update"){const r=state.rows[key()].find(x=>x.id===id);if(r){r.values=values;r.updated="Updated";r.status="PENDING"}}
 else state.rows[key()].unshift({id:"REC-"+Date.now(),values,status:"DRAFT",updated:"Inserted"});
 persist();closeModal();state.selected.clear();await render();toast(mode==="update"?"Data berhasil diupdate":"Data berhasil diinsert");
}
function persist(){try{localStorage.setItem(DEMO_MODE?DEMO_STORAGE_KEY:"rtrw_records_v3",JSON.stringify(state.rows))}catch{}}
function loadPersist(){try{Object.assign(state.rows,JSON.parse(localStorage.getItem(DEMO_MODE?DEMO_STORAGE_KEY:"rtrw_records_v3")||"{}"))}catch{}}
function deleteSelected(){seedRows();const ids=[...state.selected];if(!ids.length){toast("Pilih minimal satu record");return}modal("Konfirmasi Delete",'<p>'+ids.length+" record akan dihapus dari workspace wilayah aktif. Untuk data resmi, penghapusan kritis tetap membutuhkan approval.</p><div class=\"form-actions\"><button class=\"btn\" onclick=\"closeModal()\">Batal</button><button class=\"btn danger\" onclick=\"confirmDelete()\">Delete</button></div>")}
function confirmDelete(){const ids=state.selected;state.rows[key()]=state.rows[key()].filter(r=>!ids.has(r.id));state.selected.clear();persist();closeModal();render();toast("Record dihapus")}
let liveWorkspaceRows=[];
function exportData(){seedRows();const rows=liveWorkspaceRows.length?liveWorkspaceRows:state.rows[key()];const blob=new Blob([JSON.stringify(rows.map(r=>({id:r.id,title:r.title,status:r.status,source_table:r.source_table||null,classification:r.classification||null,payload:r.payload||{}})),null,2)],{type:"application/json"}),a=document.createElement("a");a.href=URL.createObjectURL(blob);a.download="rtrw-"+state.view+"-"+state.sub+".json";a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function printWorkspace(){window.print()}
function toggleAll(c){seedRows();state.rows[key()].forEach(r=>c?state.selected.add(r.id):state.selected.delete(r.id));render()}
function toggleRow(id,c){c?state.selected.add(id):state.selected.delete(id)}
function reportIdentityHeader(){const type=identityTypeForAccess();const p=identityCache||identityDefaults(type);const title=p.letterhead_title||p.official_name||("IDENTITAS "+type);const subtitle=p.letterhead_subtitle||p.village_name||"Wilayah RT/RW";const area=[p.district_name,p.regency_name,p.province_name].filter(Boolean).join(" · ");return '<div class="identity-report-header"><div class="identity-report-mark">'+(p.logo_url?'<img src="'+esc(p.logo_url)+'" alt="Logo">':'<span>RT/RW</span>')+'</div><div class="identity-report-text"><strong>'+esc(title)+'</strong><span>'+esc(subtitle)+'</span><small>'+esc(area||"Wilayah belum ditetapkan")+'</small><small>'+esc(p.address_line||"")+'</small></div><div class="identity-report-badge">'+esc(type)+'</div></div>'}
