async function rwReviewLoad(){const host=document.getElementById("rw-review-items");if(!host)return;if(ADMIN_PREVIEW){host.innerHTML='<div class="module-note"><b>Pratinjau UI saja.</b><span>Data review produksi sengaja tidak dimuat dalam mode pengembangan.</span></div>';return}if(!sb)return;host.innerHTML='<div class="module-note">Memuat queue RW dari Supabase...</div>';try{const {data:{user}}=await sb.auth.getUser();if(!user)throw Error("Login diperlukan");const {data:ra}=await sb.from("role_assignments").select("scope_territory_id").eq("user_id",user.id).eq("active",true).limit(1).maybeSingle();if(!ra?.scope_territory_id)throw Error("Scope wilayah belum tersedia");const resp=await sb.functions.invoke("rw-review",{body:{territory_id:ra.scope_territory_id}});if(resp.error||!resp.data?.ok)throw Error(resp.data?.error||resp.error?.message||"Gagal memuat review");const items=resp.data.items||[];host.innerHTML=items.length?items.map((x,i)=>{const r=x.record;const label=r.business_name||r.name||r.title||r.actor_name||r.object_name||r.event_type||r.service_type||x.table;return '<div class="queue"><div><span class="queue-dot"></span><div><b>'+esc(label)+'</b><small>'+esc(x.table)+' · '+esc(x.status)+'</small></div><div class="row-actions"><button class="btn" data-rw-action="RW_APPROVE" data-rw-table="'+esc(x.table)+'" data-rw-id="'+esc(r.id)+'" data-rw-territory="'+esc(r.territory_id)+'">Teruskan</button><button class="btn danger-outline" data-rw-action="RW_CORRECT" data-rw-table="'+esc(x.table)+'" data-rw-id="'+esc(r.id)+'" data-rw-territory="'+esc(r.territory_id)+'">Koreksi</button></div></div></div>'}).join(""):'<div class="module-note">Tidak ada data yang menunggu review RW pada scope aktif.</div>';}catch(e){host.innerHTML='<div class="module-note">Review RW belum dapat dimuat: '+esc(e.message)+'</div>';}}
async function rwAction(entity_type,entity_id,territory_id,action){const reason=action==="RW_CORRECT"?prompt("Alasan koreksi RW:"):null;if(action==="RW_CORRECT"&&!reason)return;try{const resp=await sb.functions.invoke("workflow-transition",{body:{entity_type,entity_id,territory_id,action,reason}});if(resp.error||!resp.data?.ok)throw Error(resp.data?.error||resp.error?.message||"Workflow gagal");toast(action==="RW_APPROVE"?"Data diteruskan ke Desa":"Data dikembalikan untuk koreksi");rwReviewLoad();}catch(e){toast("Workflow gagal: "+e.message);}}
