function appendCompanionMessage(role,content){
  state.companionMessages.push({role,content:String(content||"").slice(0,6000)});
  state.companionMessages=state.companionMessages.slice(-20);
  const list=document.getElementById("ai-companion-messages");
  if(!list)return;
  const empty=list.querySelector(".ai-companion-empty");if(empty)empty.remove();
  const item=state.companionMessages[state.companionMessages.length-1];
  const bubble=document.createElement("div");bubble.className="ai-companion-message "+(role==="user"?"user":"assistant");
  const label=document.createElement("span");label.textContent=role==="user"?"Anda":"Zofia";
  const text=document.createElement("p");text.textContent=item.content;
  bubble.append(label,text);list.appendChild(bubble);list.scrollTop=list.scrollHeight;
}
async function sendCompanionMessage(event){
  event.preventDefault();
  const input=document.getElementById("ai-companion-input"),button=document.getElementById("ai-companion-send");
  const message=String(input?.value||"").trim();
  if(!message||!sb||!C.aiCompanionEnabled)return;
  appendCompanionMessage("user",message);input.value="";input.disabled=true;button.disabled=true;button.textContent="…";
  const persona=companionPersona();
  const territoryId=(persona==="PENGURUS_RT"||persona==="PENGURUS_RW")?(access.scopes||[]).find(item=>item.territoryId)?.territoryId||null:null;
  try{
    const response=await sb.functions.invoke("ai-companion",{body:{message,role:persona,territory_id:territoryId}});
    if(response.error||!response.data?.reply){
      const code=response.data?.error||response.error?.message||"AI Companion belum tersedia";
      appendCompanionMessage("assistant",code.includes("ROLE_NOT_ASSIGNED")||code.includes("SCOPE_REQUIRED")?"Akses pendamping operasional belum aktif untuk wilayah ini. Minta administrator memeriksa penugasan dan cakupan wilayah.":"Maaf, Zofia belum dapat menjawab saat ini. Silakan coba kembali beberapa saat lagi.");
    }else{
      appendCompanionMessage("assistant",response.data.reply);
    }
  }catch(_error){
    appendCompanionMessage("assistant","Koneksi ke Zofia sedang bermasalah. Silakan coba kembali.");
  }finally{
    input.disabled=false;button.disabled=false;button.textContent="Kirim";input.focus();
  }
}


function commercialTrialWidget(user){
  if(!user||ADMIN_PREVIEW||!sb||C.commercialTrialEnabled!==true)return "";
  const orgIds=[...new Set((access.scopes||[]).map(item=>item.organizationId).filter(Boolean))];
  const orgId=orgIds[0]||"";
  const prior=orgId?state.commercialTrialResults[orgId]:null;
  const blocked=!!(prior&&(prior.trialStartedAt||prior.currentStatus));
  const trialActive=!!(prior&&prior.currentStatus==="TRIALING"&&prior.trialStartedAt);
  const options=orgIds.map(id=>'<option value="'+esc(id)+'">'+esc("Organisasi · "+String(id).slice(-8))+'</option>').join("");
  const notice=orgIds.length
    ?(trialActive?"Trial aktif sampai "+new Date(prior.trialEndsAt).toLocaleString("id-ID",{dateStyle:"medium",timeStyle:"short"})+".":blocked?(prior.trialStartedAt?"Trial sudah digunakan. Status: "+String(prior.currentStatus||prior.status||"EXPIRED")+".":"Organisasi sudah memiliki langganan "+String(prior.currentStatus||prior.status)+"."):"Aktivasi trial tersedia untuk organisasi dengan penugasan aktif.")
    :"Akun ini belum terhubung ke organisasi. Admin wilayah perlu membuat organisasi dan penugasan terlebih dahulu.";
  return '<aside class="commercial-trial-widget" aria-label="Aktivasi Trial 7 Hari"><div class="commercial-trial-head"><span class="commercial-trial-icon">7</span><div><b>Trial 7 Hari</b><small>Gratis · maksimal 1 perangkat</small></div></div><p id="commercial-trial-status">'+esc(notice)+'</p>'+(orgIds.length>1?'<label for="commercial-trial-org">Pilih organisasi</label>':"")+(orgIds.length>1?'<select id="commercial-trial-org" onchange="refreshCommercialTrialStatus()">'+options+'</select>':(orgId?'<input id="commercial-trial-org" type="hidden" value="'+esc(orgId)+'">':""))+'<button type="button" id="commercial-trial-start" onclick="startCommercialTrial()" '+(!orgId||blocked||state.commercialTrialLoading?"disabled":"")+'>'+(trialActive?"Trial Aktif":blocked?"Trial Tidak Tersedia":state.commercialTrialLoading?"Memproses…":"Aktifkan Trial")+'</button></aside>';
}

async function refreshCommercialTrialStatus(){
  if(!sb||C.commercialTrialEnabled!==true||ADMIN_PREVIEW)return;
  const orgIds=[...new Set((access.scopes||[]).map(item=>item.organizationId).filter(Boolean))];
  if(!orgIds.length)return;
  try{
    const result=await sb.from("organization_subscriptions")
      .select("organization_id,status,trial_started_at,trial_ends_at,current_period_ends_at,created_at")
      .in("organization_id",orgIds).order("created_at",{ascending:false}).limit(50);
    if(result.error||!Array.isArray(result.data))return;
    const currentStatuses=["TRIALING","ACTIVE","GRACE","PAST_DUE","SUSPENDED"];
    for(const id of orgIds){
      const rows=result.data.filter(row=>row.organization_id===id);
      const trial=rows.find(row=>row.trial_started_at)||null;
      const current=rows.find(row=>currentStatuses.includes(row.status))||null;
      const chosen=current||trial;
      if(chosen){
        state.commercialTrialResults[id]={
          organizationId:id,status:chosen.status,currentStatus:current?.status||null,
          trialStartedAt:trial?.trial_started_at||chosen.trial_started_at||null,
          trialEndsAt:trial?.trial_ends_at||chosen.trial_ends_at||null,
          currentPeriodEndsAt:current?.current_period_ends_at||null
        };
      }
    }
    const orgId=document.getElementById("commercial-trial-org")?.value||orgIds[0];
    const prior=state.commercialTrialResults[orgId]||null;
    const status=document.getElementById("commercial-trial-status");
    const button=document.getElementById("commercial-trial-start");
    const blocked=!!(prior&&(prior.trialStartedAt||prior.currentStatus));
    const activeTrial=!!(prior&&prior.currentStatus==="TRIALING"&&prior.trialStartedAt);
    if(status&&prior){
      status.textContent=activeTrial
        ?"Trial aktif sampai "+new Date(prior.trialEndsAt).toLocaleString("id-ID",{dateStyle:"medium",timeStyle:"short"})+"."
        :prior.trialStartedAt
          ?"Trial sudah digunakan. Status: "+String(prior.currentStatus||prior.status||"EXPIRED")+"."
          :"Organisasi sudah memiliki langganan "+String(prior.currentStatus||prior.status)+".";
    }
    if(button&&!state.commercialTrialLoading){
      button.disabled=blocked;
      button.textContent=activeTrial?"Trial Aktif":blocked?"Trial Tidak Tersedia":"Aktifkan Trial";
    }
  }catch(_error){}
}
function deviceInstallationId(){
  const key="rtrw_sid_device_installation_v1";
  try{
    let id=localStorage.getItem(key);
    if(!/^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(id||"")){
      if(!globalThis.crypto?.randomUUID)throw new Error("Browser tidak mendukung identitas perangkat aman.");
      id=crypto.randomUUID();
      localStorage.setItem(key,id);
    }
    return id;
  }catch(error){throw new Error("Penyimpanan identitas perangkat tidak tersedia. Aktifkan penyimpanan situs lalu coba lagi.");}
}
async function verifyDeviceEntitlements(){
  if(!sb||!access||ADMIN_PREVIEW||C.commercialTrialEnabled!==true)return null;
  const orgIds=[...new Set((access.scopes||[]).map(item=>item.organizationId).filter(Boolean))];
  if(!orgIds.length)return null;
  const result=await sb.from("organization_subscriptions")
    .select("organization_id,status,current_period_ends_at")
    .in("organization_id",orgIds).limit(50);
  if(result.error)return {blocked:true,message:"Status langganan dan perangkat tidak dapat diverifikasi. Akses operasional ditahan sampai koneksi pulih."};
  const now=Date.now();
  const current=(result.data||[]).filter(row=>["TRIALING","ACTIVE","GRACE"].includes(row.status)&&Date.parse(row.current_period_ends_at)>now);
  if(!current.length)return {blocked:true,message:"Tidak ada langganan aktif untuk organisasi ini. Trial mungkin sudah berakhir atau paket belum diaktifkan. Aktifkan Trial 7 Hari atau hubungi administrator."};
  let deviceId;
  try{deviceId=deviceInstallationId()}catch(error){return {blocked:true,message:error.message||"Identitas perangkat tidak tersedia."};}
  for(const sub of current){
    const response=await sb.functions.invoke("register-device",{body:{organization_id:sub.organization_id,device_id:deviceId,device_label:"Browser web"}});
    const code=response.data?.error||response.error?.message||"";
    if(response.error||response.data?.error){
      const message=code==="DEVICE_LIMIT_REACHED"
        ?"Batas perangkat paket ini sudah tercapai. Hubungi administrator organisasi untuk mencabut perangkat lama."
        :code==="SUBSCRIPTION_INACTIVE"
          ?"Langganan sudah tidak aktif. Periksa status paket atau hubungi administrator."
          :"Perangkat tidak dapat diverifikasi oleh server. Akses operasional ditahan untuk keamanan.";
      return {blocked:true,message};
    }
  }
  return null;
}
function showDeviceAccessBlock(message){
  document.getElementById("landing").innerHTML="";
  document.getElementById("app").innerHTML='<div class="access-pending"><div class="access-pending-icon">⌁</div><div class="eyebrow dark">PEMERIKSAAN PERANGKAT</div><h2>Perangkat belum diizinkan.</h2><p>'+esc(message)+'</p><button class="btn" type="button" onclick="signOut()">Keluar</button></div>';
}
async function startCommercialTrial(){
  if(!sb||C.commercialTrialEnabled!==true||state.commercialTrialLoading)return;
  const orgId=document.getElementById("commercial-trial-org")?.value;
  if(!orgId){toast("Organisasi belum tersedia untuk akun ini.");return;}
  state.commercialTrialLoading=true;
  const button=document.getElementById("commercial-trial-start");
  if(button){button.disabled=true;button.textContent="Memproses…";}
  try{
    const response=await sb.functions.invoke("start-trial",{body:{organization_id:orgId,device_id:deviceInstallationId(),device_label:"Browser web"}});
    let payload=response.data;
    if(response.error&&!payload){
      try{payload=await response.error.context?.clone?.().json()}catch(_ignored){}
    }
    if(response.error||!payload?.subscription){
      const code=payload?.error||response.error?.message||"";
      const messages={
        TRIAL_ALREADY_USED:"Organisasi ini sudah menggunakan Trial 7 Hari.",
        SUBSCRIPTION_ALREADY_CURRENT:"Organisasi sudah memiliki langganan aktif atau ditangguhkan.",
        TRIAL_OR_SUBSCRIPTION_ALREADY_EXISTS:"Trial atau langganan sudah pernah diaktifkan untuk organisasi ini.",
        ORGANIZATION_ACCESS_DENIED:"Akses administrator untuk organisasi ini belum terverifikasi.",
        TRIAL_PLAN_NOT_CONFIGURED:"Aktivasi trial belum siap di server."
      };
      const message=messages[code]||"Aktivasi trial gagal. Silakan coba kembali atau hubungi administrator.";
      const status=document.getElementById("commercial-trial-status");if(status)status.textContent=message;
      const conflict=["TRIAL_ALREADY_USED","SUBSCRIPTION_ALREADY_CURRENT","TRIAL_OR_SUBSCRIPTION_ALREADY_EXISTS"].includes(code);
      if(button){button.disabled=conflict;button.textContent=conflict?"Trial Tidak Tersedia":"Coba Lagi";}
      if(conflict)setTimeout(refreshCommercialTrialStatus,0);
      return;
    }
    const sub=response.data.subscription;
    state.commercialTrialResults[orgId]={organizationId:orgId,status:sub.status,currentStatus:sub.status,trialStartedAt:sub.trial_started_at,trialEndsAt:sub.trial_ends_at,currentPeriodEndsAt:sub.current_period_ends_at};
    const status=document.getElementById("commercial-trial-status");
    if(status)status.textContent="Trial aktif sampai "+new Date(sub.trial_ends_at).toLocaleString("id-ID",{dateStyle:"medium",timeStyle:"short"})+".";
    if(button){button.disabled=true;button.textContent="Trial Aktif";}
    toast("Trial 7 Hari berhasil diaktifkan.");
  }catch(_error){
    const status=document.getElementById("commercial-trial-status");if(status)status.textContent="Layanan aktivasi sedang tidak tersedia. Coba kembali nanti.";
    if(button){button.disabled=false;button.textContent="Coba Lagi";}
  }finally{state.commercialTrialLoading=false;}
}

