function openMobileSidebar(){if(window.innerWidth<=800){document.body.classList.add("menu-open");document.querySelectorAll("[data-sidebar-toggle]").forEach(el=>el.setAttribute("aria-expanded","true"))}}
document.addEventListener("click",function(e){
 const toggle=e.target.closest("[data-sidebar-toggle]");
 if(toggle){e.preventDefault();if(toggle.dataset.sidebarToggle==="open")openMobileSidebar();else closeMobileSidebar();return}
 if(window.innerWidth<=800&&e.target.closest(".sidebar nav button")){closeMobileSidebar()}
});
window.addEventListener("resize",()=>{if(window.innerWidth>800)closeMobileSidebar()});
